mapper.select:
SELECT a.workspace_id, a.person_id, a.criterion_id, a.answer, a.answered_by_id, a.answered_at
FROM person_qualification_answer a
WHERE a.workspace_id = #{workspaceId} AND a.person_id = #{personId}

mapper.delete:
DELETE FROM person_qualification_answer
WHERE workspace_id = #{workspaceId}
  AND person_id = #{personId}
  AND criterion_id = #{criterionId}
